  'result.benefit_work_history_link': 'виписка про ваш трудовий стаж (на порталі Seguridad Social)',
  'result.benefit_just_cause':
    'Є винятки. Звільнення з однієї з цих причин є законним статусом безробітного (situación legal de desempleo) і, якщо ви відповідаєте іншим вимогам, дає право на допомогу: переведення в інше місце (art. 40 ET), істотна зміна ваших умов праці на гірше (art. 41.3 ET), серйозне порушення з боку роботодавця, наприклад, коли вам не платять або раз у раз платять із запізненням (art. 50 ET), або гендерне чи сексуальне насильство (art. 49.1.m ET). Це передбачає art. 267.1.a.5.º LGSS. Розірвання договору на підставі art. 50 зазвичай оформлює суд.',
  'result.benefit_calculation':
    'База — це середнє значення внесків на випадок безробіття за останні 180 днів; тут її розраховано з вашої річної зарплати брутто разом із додатковими виплатами, поділеної на 12, у межах мінімальної та максимальної баз 2026 року. Перші 180 днів виплачується 70 % бази, далі — 60 %, з мінімумом і максимумом залежно від кількості дітей на утриманні. Тривалість визначається шкалою art. 269.1: 360 днів сплачених внесків за останні 6 років дають 120 днів допомоги, і кожні наступні 180 додають 60, до 720.',
  'guide.title': 'Як розраховується остаточний розрахунок (finiquito)',
