  'final_pay.app_name': 'Калькулятор остаточного розрахунку',
  'documents.start.question': 'З чого ви хочете почати?',
  'documents.start.help':
    'Ви можете завантажити документи, які вам дав роботодавець, щоб заповнити дані тим, що в них буде зчитано, або ввести їх самі. Перш ніж щось розраховувати, ви перевіряєте кожне значення.',
  'documents.start.choices': 'З чого почати',
  'documents.start.upload': 'Завантажте свої документи',
  'documents.start.upload_hint':
    'ШІ зчитує дані, а ви їх підтверджуєте. Безкоштовно, 2 зчитування на день.',
  'documents.start.manual': 'Заповнити вручну',
  'documents.start.manual_hint': 'Ви вводите дані самі, і ніщо не залишає вашого пристрою.',
  'documents.start.unavailable':
    'Автоматичне зчитування документів зараз недоступне. Ви можете ввести дані вручну; розрахунок той самий.',
  'documents.upload.question': 'Завантажте свої документи',
