  'documents.upload.files_hint':
    'Наприклад: лист про звільнення, остаточний розрахунок (finiquito), ваші розрахункові листи, довідка від роботодавця (certificado de empresa) або виписка про трудовий стаж (vida laboral), у будь-якому порядку. До 25 фото або сторінок PDF загалом. Фото і сторінки PDF перетворюються на зображення на вашому пристрої перед надсиланням.',
  'documents.upload.drop': 'Перетягніть сюди фото або PDF чи виберіть їх кнопкою.',
  'documents.upload.camera': 'Зробити фото',
