  'documents.done.another': 'Завантажити ще документи',
  'documents.pass.title': 'Звіт у PDF і лист «recibí no conforme»',
  'documents.pass.text':
    'Завантажте повний звіт із покроковим розрахунком, правовими джерелами і листом «recibí no conforme» за 4,99 €. Вони створюються на вашому пристрої.',
  'documents.pass.price':
    '4,99 € з IVA. Один платіж, без облікового запису і без передплати. Абонемент діє 7 днів і лише в цьому браузері: за цей час ви можете повторити чи виправити свою перевірку, зчитати до 15 пакетів документів і знову завантажити звіт і лист без повторної оплати. На іншому пристрої, у приватному вікні або якщо ви видалите дані браузера, він втрачається.',
  'documents.pass.waiver':
    'Я хочу отримати звіт зараз. Я знаю, що оскільки це цифровий вміст, який надається одразу, я втрачаю право на відмову від договору (desistimiento, art. 103.m Ley General para la Defensa de los Consumidores y Usuarios).',
  'documents.pass.conditions': 'Умови продажу',
