    'Я отримав(-ла) пропозицію остаточного розрахунку (finiquito) у зв’язку із закінченням мого договору, з датою звільнення {fecha}, і зазначаю, що не погоджуюся з такими сумами:',
  'client.documents.letter.body_general':
    'Я отримав(-ла) пропозицію остаточного розрахунку (finiquito) у зв’язку із закінченням мого договору, з датою звільнення {fecha}, і зазначаю, що отримую її, не висловлюючи згоди з її змістом.',
