  'privacy.title': 'Конфіденційність · eslojusto.es',
  'privacy.description':
    'Те, що ви вводите під час перевірки остаточного розрахунку, не залишає вашого браузера. Cookie немає, а кроки вимірюються без вашої ідентифікації, за допомогою PostHog у Європейському Союзі.',
  'privacy.h1': 'Конфіденційність',
  'privacy.summary': 'Коротко',
