  'employment.documents.start_help':
    'Ви можете завантажити свій договір та інші документи щодо роботи, щоб заповнити дані тим, що з них буде зчитано, або ввести їх самі. Перед будь-якою перевіркою ви підтверджуєте кожне значення.',
  'employment.documents.upload':
    'Завантажте свій договір і, якщо вони у вас є, розрахункові листи, оголошення про вакансію і виписку про трудовий стаж (vida laboral)',
  'employment.documents.files_hint':
    'Договір із додатками і, якщо вони у вас є, ваші розрахункові листи, оголошення про вакансію або виписка про трудовий стаж, у будь-якому порядку. До 25 фото або сторінок PDF загалом. Фото і сторінки PDF перетворюються на зображення на вашому пристрої перед надсиланням.',
  'employment.documents.consent':
    'Я даю явну згоду на те, щоб ШІ зчитав ці документи і заповнив форму. Я знаю, що вони можуть містити чутливі дані, як-от членство у профспілці, лікарняний чи інвалідність. Вони зчитуються в Європейському Союзі й не зберігаються.',
  'employment.pass.title': 'Деталі, звіт і лист',
  'employment.pass.text':
    'За 4,99 € ви бачите покроковий розрахунок кожного пункту вашого договору (рік за роком і розрахунковий лист за розрахунковим листом, із чинною нормою та її джерелом) і завантажуєте звіт у PDF та, якщо у вашій перевірці є пункти для нього, лист до компанії. Вони створюються на вашому пристрої.',
  'employment.pass.price':
    '4,99 € з IVA. Один платіж, без облікового запису і без передплати. Абонемент діє 7 днів і лише в цьому браузері, зокрема для перевірок остаточного розрахунку та оренди: за цей час ви можете повторити чи виправити свою перевірку, зчитати до 15 пакетів документів, знову переглянути деталі й завантажити звіт і лист без повторної оплати. На іншому пристрої, у приватному вікні або якщо ви видалите дані браузера, він втрачається.',
  'employment.pass.paid_help':
    'Якщо ви оплатили в цьому браузері і не бачите деталей і завантажень, відновіть тут свій абонемент. Це працює лише в браузері, у якому ви оплатили.',
  'employment.pass.waiver':
    'Я хочу побачити деталі і звіт зараз. Я знаю, що оскільки це цифровий вміст, який надається одразу, я втрачаю право на відмову від договору (desistimiento, art. 103.m Ley General para la Defensa de los Consumidores y Usuarios).',
