  'rent_indices.note_flash':
    'Попередній IPC (adelantado) — це оцінка, яку INE дає наприкінці кожного місяця; остаточний виходить приблизно через два тижні й іноді відрізняється на одну десяту пункту. Для IRAV попереднього значення немає.',
  'rent_indices.note_igc':
    'INE публікує IGC таким, яким він виходить за формулою, і часто він від’ємний. Для перегляду ціни за цим індексом Ley 2/2015 обмежує його межами від {min} до {max}: якщо він від’ємний, перегляд становить {min}, а якщо перевищує {max}, береться {max}.',
