  'rent_indices.cap.three.when': 'У 2024 р.',
  'rent_indices.cap.three.rule':
    '3 % або IPC, якщо він нижчий. Нова домовленість могла замінити 3 % іншим підвищенням. Якщо ваш орендодавець — великий власник житла (gran tenedor), підвищення не може перевищувати 3 %, навіть якщо ви домовилися про інше підвищення. З 26-05-2023 великим власником житла є той, хто має понад десять об’єктів нерухомості житлового призначення або понад 1.500 m² житлової площі, а в оголошеній зоні напруженого ринку житла автономна спільнота може знизити цей поріг до п’яти й більше об’єктів житлового призначення в цій зоні.',
