  'rent_indices.faq': 'Поширені запитання',
  'rent_indices.faq.what_is_irav': 'Що таке IRAV?',
  'rent_indices.faq.what_is_irav_answer':
    'Це індекс, який INE публікує щомісяця, щоб обмежити щорічне підвищення орендної плати за житло (додаткове положення 11.ª LAU). Це найменше значення з IPC, базового IPC і середнього, яке наближає результат до 2 %. Він слугує граничним рівнем з 1 січня 2025 р.',
