  'rental.contract.start': 'Дата заселення',
  'rental.contract.start_hint':
    'День, з якого діє договір: від нього відраховується кожна річниця.',
  'rental.landlord.question': 'Ваш орендодавець',
  'rental.landlord.type': 'Хто здає вам житло?',
  'rental.landlord.type_hint':
    'Це зазначено в договорі: ім’я особи або назва компанії (S.L., S.A.).',
  'rental.large.question': 'Великий власник житла',
  'rental.landlord.large': 'Чи ваш орендодавець — великий власник житла (gran tenedor)?',
  'rental.landlord.large_hint':
    'Великий власник житла — це той, хто має понад десять міських об’єктів нерухомості житлового призначення або понад 1.500 m² житлової площі, не враховуючи гаражів і комор (art. 3.k Ley 12/2023); у зоні напруженого ринку житла автономна спільнота може знизити цей поріг до п’яти й більше об’єктів. З 08-10-2026 Real Decreto-ley 29/2026, що очікує затвердження Конгресом (convalidación), додає, що цей статус підтверджується довідкою з Registro de la Propiedad (реєстру власності) і що кожна житлова одиниця будинку вважається окремим об’єктом, навіть якщо поділ будинку на окремі приміщення не зареєстровано. Бути компанією недостатньо: компанія з невеликою кількістю квартир не є великим власником житла.',
  'rental.home.question': 'Де розташоване житло',
  'rental.landlord.region': 'Автономна спільнота',
  'rental.landlord.region_hint': 'Та, де розташоване житло.',
  'rental.landlord.region_choose': 'Виберіть автономну спільноту',
  'rental.landlord.stressed': 'Чи розташоване житло в зоні напруженого ринку житла?',
  'rental.landlord.stressed_hint':
    'Оголошена зона напруженого ринку житла (zona tensionada). Якщо ви не знаєте, у результаті буде вказано, де це перевірити.',
  'rental.entry.question': 'Що ви заплатили під час заселення',
  'rental.entry.help':
    'Заставний депозит, інші гарантії і те, що з вас стягнули агентство чи орендодавець на початку. Якщо якихось даних у вас немає, залиште поле порожнім.',
