  'rental.fees.question': 'Інші платежі під час заселення',
  'rental.entry.fees': 'Чи платили ви агентству або орендодавцю ще щось під час заселення?',
  'rental.entry.fees_hint':
    'Винагорода, оформлення договору, перевірка платоспроможності, бронювання чи оформлення документів.',
