  'mortgage.answer.no': 'Ні',
  'mortgage.answer.unknown': 'Не знаю',
  'mortgage.loan.question': 'Ваша іпотека',
  'mortgage.loan.help': 'Майте під рукою нотаріальний акт і, якщо вони у вас є, рахунки до нього.',
  'mortgage.loan.kind': 'Що це?',
  'mortgage.loan.kind.standard': 'Іпотека на житло',
  'mortgage.loan.kind.developer_subrogation':
    'Іпотека забудовника, яку ви перейняли під час купівлі (subrogación)',
  'mortgage.loan.kind.multicurrency': 'Мультивалютна іпотека',
