  'mortgage.holder.borrower': 'Хто її оформив?',
  'mortgage.holder.borrower.individual': 'Я, як фізична особа',
  'mortgage.holder.borrower.company': 'Компанія або товариство',
  'mortgage.holder.purpose': 'На що оформлено іпотеку?',
  'mortgage.holder.purpose.housing': 'Житло, з гаражем чи коморою',
  'mortgage.holder.purpose.business': 'Приміщення, склад чи інша нерухомість для бізнесу',
  'mortgage.deed.question': 'Нотаріальний акт',
  'mortgage.deed.on': 'Дата нотаріального акта',
  'mortgage.deed.on_hint': 'Дата нотаріального акта кредиту, підписаного в нотаріуса.',
  'mortgage.deed.amount': 'Сума кредиту',
  'mortgage.deed.amount_hint': 'У євро. Якщо ви не знаєте, залиште порожнім.',
  'mortgage.deed.consumer': 'Ви оформили іпотеку як приватна особа, для свого житла?',
  'mortgage.deed.consumer_hint':
    'У нотаріальному акті зазвичай зазначено, для чого кредит. Розподіл Верховного суду Іспанії стосується лише того, хто оформив її як приватна особа.',
  'mortgage.rate.question': 'Процентна ставка',
  'mortgage.rate.type': 'Яка в неї ставка?',
  'mortgage.rate.type.fixed': 'Фіксована',
  'mortgage.rate.type.variable': 'Змінна',
  'mortgage.rate.type.mixed': 'Змішана',
  'mortgage.rate.revision': 'Як часто (у місяцях) переглядається ставка',
  'mortgage.rate.revision_hint': 'Зазвичай 6 або 12. Якщо ви не знаєте, залиште порожнім.',
