  'client.mortgage.calculation.information.transparency_act':
    'Не пізніше ніж за день до підписання нотаріального акта нотаріус консультує вас і фіксує це в протоколі, за який з вас не стягують плати, а нотаріальний акт на нього посилається (art. 15).',
  'client.mortgage.calculation.information.handwritten_statement':
    'З 15-05-2013 до 15-06-2019, якщо ви оформили іпотеку як фізична особа, на житло або для купівлі чи збереження земельної ділянки чи будівлі, і вона мала обмеження зміни ставки, як-от нижню і верхню межу, «en los cuales el límite de variabilidad a la baja sea inferior al límite de variabilidad al alza», інструмент хеджування ризику процентної ставки або надавалася в іноземній валюті, нотаріальний акт мав містити власноручно написаний текст, у якому зазначалося, що вас попередили про її ризики (art. 6 Ley 1/2013).',
  'client.mortgage.calculation.information.limitation_rule':
    'За позицією Суду Європейського Союзу, строк, щоб звернутися щодо сплаченого за умовою про витрати, не може починати відлічуватися з дня оплати, а лише з моменту, коли стало можливо дізнатися, що умова недійсна. Це правило, а не розрахунок для вашого випадку.',
  'client.mortgage.calculation.information.prior_step_439bis':
    'З 03-04-2025 закон передбачає конкретний попередній крок, перш ніж звертатися до суду щодо умов іпотеки (art. 439 bis Ley de Enjuiciamiento Civil). За посиланням — текст закону.',
