    'За 4,99 € ви завантажуєте звіт у PDF із таблицею платежів, за якою розраховано TAE, внеском кожної витрати і граничним рівнем за дострокове погашення, а якщо у вашій перевірці є для цього суми, — лист щодо компенсації за дострокове погашення. Вони створюються на вашому пристрої.',
  'credit.pass.price':
    '4,99 € з IVA. Один платіж, без облікового запису і без передплати. Абонемент діє 7 днів і лише в цьому браузері, зокрема для інших перевірок на сайті: за цей час ви можете повторити чи виправити свою перевірку і знову завантажити звіт і лист без повторної оплати. На іншому пристрої, у приватному вікні або якщо ви видалите дані браузера, він втрачається.',
