    'Для позик судову практику Верховного суду Іспанії щодо цієї різниці ще не перевірено в тексті рішення, тому наведено лише різницю, без порівняння з будь-яким порогом.',
  'client.credit.calculation.indicator.revolving_criterion':
    'Для револьверних карток Верховний суд Іспанії бере за орієнтир різницю із середньою ставкою понад 6 відсоткових пунктів (STS 258/2023). Це судова практика, а не норма.',
