  'client.credit.calculation.dealer_discount.review_it':
    'Те, що автосалон стягує за втрату знижки, наданої за фінансування, не є компенсацією кредитора, тому це не порівнюється з граничним рівнем за art. 30. У договорі має бути зазначено ціну при оплаті готівкою (art. 16.2), і ви можете не фінансувати купівлю, а оплатити її так, як домовилися з продавцем (art. 26.3). Що відбувається з цією знижкою, залежить від того, що встановлює ваш договір.',
