  'client.credit.calculation.information.linked_credit':
    'Якщо позика слугує лише для оплати купівлі конкретного товару чи послуги і становить із цією купівлею єдине ціле, це пов’язаний кредит (crédito vinculado, art. 29.1). Тоді в договорі має бути зазначено товар і його ціну при оплаті готівкою (art. 16.2.e); якщо ви відмовляєтеся від купівлі, позика перестає вас зобов’язувати без штрафу (art. 29.2); а якщо товар не надійшов або не відповідає договору, у деяких випадках ці права діють і щодо кредитора (art. 29.3).',
  'client.credit.calculation.information.cash_option':
    'І ви можете не фінансувати купівлю, а оплатити її так, як домовилися з продавцем (art. 26.3).',
  'client.credit.calculation.information.revolving_info':
    'Наказ про прозорість банківських послуг (orden de transparencia bancaria) передбачає, що за револьверною карткою щонайменше раз на квартал надається інформація про заборгованість, ставку, платіж, а також про те, коли і скільки ви сплатите до повного погашення (art. 33 quinquies), і що на ваш запит протягом 5 робочих днів вам нададуть відомості про сплачене і заборгованість із розбивкою, а також графік погашення (art. 33 sexies). Не перевірено, на які установи й попередні договори це поширюється, тому тут не стверджується, що ваша кредитна установа зобов’язана це робити.',
