  'client.credit.letter.about.revolving':
    'Звертаюся до Вас щодо моєї картки з відстроченим платежем (revolving), оформленої {fecha}.',
  'client.credit.letter.information.title': 'Прохання надати інформацію про мій кредит',
  'client.credit.letter.information.schedule':
    'Art. 16.2.i Ley 16/2011 про договори споживчого кредиту закріплює право отримати на запит, безкоштовно і в будь-який момент дії договору, виписку у формі графіка погашення. Прошу Вас надати мені графік погашення мого кредиту.',
  'client.credit.letter.information.breakdown':
    'Прошу Вас надати розбивку того, що я сплатив(-ла) дотепер, із зазначенням частини, що пішла на відсотки, комісії та основну суму, а також того, що залишилося сплатити. Наказ про прозорість банківських послуг (orden de transparencia bancaria) передбачає таку розбивку для карток з відстроченим платежем.',
