  'client.credit.letter.repayment.filename': 'eslojusto-carta-compensacion-credito.pdf',
  'client.credit.report.title': 'Перевірка вашої позики або картки',
  'client.credit.report.intro':
    'Цей звіт порівнює суми вашого кредиту з тим, що каже закон, позиція за позицією, за даними, які ви підтвердили під час перевірки: TAE, що з них випливає, як вона співвідноситься із середньою ставкою Banco de España, граничний рівень за дострокове погашення і строк для відмови від договору. Якщо результат залежить від даних, яких ви не знаєте, наведено кожен розрахунок. Звіт інформує про закон і не є юридичною консультацією.',
