  'household.description':
    'Перевірте зарплату, робочий час, відпустку, остаточний розрахунок (finiquito) і припинення трудових відносин (desistimiento) за вашою роботою в домі сім’ї на відповідність закону, суму за сумою і зі статтею.',
  'household.h1': 'Перевірте, чи справедливо вам платять за роботу в домі сім’ї',
  'household.lead':
    'Ви працюєте в домі сім’ї: порівняйте свою зарплату, робочий час і, якщо робота закінчилася, те, як вона закінчилася, з тим, що встановлює закон. Біля кожної суми — стаття, з якої вона випливає.',
