    'Випробувальний строк: письмово і не більше двох місяців, якщо колективний договір не встановлює іншого, з попередженням не більше ніж за сім календарних днів (art. 6.2).',
  'client.household.unchecked.prevention':
    'Охорона праці в домі (prevención de riesgos laborales, Real Decreto 893/2024).',
