  'client.household.error.amount_range':
    'Введіть правдоподібну суму без знака мінус; зарплату — більшу за нуль.',
  'client.household.error.hours_range': 'Введіть правдоподібну кількість годин.',
  'client.household.error.count_range': 'Введіть правдоподібне ціле число.',
