    'Особа, яка проживає в домі сім’ї, не отримує погодинної оплати.',
  'client.household.error.notice_before_start':
    'Цей строк попередження починається раніше, ніж ви почали працювати.',
  'client.household.error.missing_value': 'Бракує цих даних.',
  'client.household.error.missing_choice': 'Виберіть відповідь.',
